import { API_BASE_URL } from '../config/api';

export interface Place {
  id: string;
  name: string;
  category: 'cafe' | 'park' | 'museum' | 'gym';
  lat: number;
  lng: number;
  rating: number;
}

export interface UserLocation {
  lat: number;
  lng: number;
}

export async function fetchPlaces(): Promise<Place[]> {
  const response = await fetch(`${API_BASE_URL}/places`);
  if (!response.ok) throw new Error(`Places failed with status ${response.status}`);
  return (await response.json()) as Place[];
}

export function distanceKm(a: UserLocation, b: { lat: number; lng: number }): number {
  const rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchPlaces, distanceKm, type Place, type UserLocation } from '../services/places';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  text: '#f5f5f0',
  surface: '#1a1f1a',
  warn: '#eab308',
  border: '#242a24',
  muted: '#8a8f8a',
  danger: '#ff6b5e',
}

const USER: UserLocation = { lat: 37.7749, lng: -122.4194 };
const CATEGORY_ICON: Record<Place['category'], string> = { cafe: '☕', park: '🌳', museum: '🏛', gym: '🏋' };

export function PlacesScreen(): JSX.Element {
  const [places, setPlaces] = useState<Place[]>([]);
  const [unit, setUnit] = useState<'km' | 'mi'>('km');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [denied, setDenied] = useState(false);

    const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchPlaces();
      setPlaces(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load places.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const sorted = useMemo(() => {
    const withDistance = places.map(place => ({ place, km: distanceKm(USER, place) })).sort((a, b) => a.km - b.km);
    return withDistance;
  }, [places]);

  const formatDistance = useCallback((km: number) => {
    if (unit === 'mi') return `${(km * 0.621371).toFixed(1)} mi`;
    return `${km.toFixed(1)} km`;
  }, [unit]);

  const renderItem = useCallback(({ item }: { item: { place: Place; km: number } }) => (
    <View style={styles.row}>
      <Text style={styles.icon}>{CATEGORY_ICON[item.place.category]}</Text>
      <View style={styles.info}>
        <Text style={styles.name}>{item.place.name}</Text>
        <Text style={styles.meta}>{item.place.category} · ★ {item.place.rating.toFixed(1)}</Text>
      </View>
      <Text style={styles.distance}>{formatDistance(item.km)}</Text>
    </View>
  ), [formatDistance]);

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.header}>
        <Text style={styles.title}>Nearby</Text>
        <TouchableOpacity
          style={styles.toggle}
          onPress={() => setUnit(u => (u === 'km' ? 'mi' : 'km'))}
          accessibilityRole="button"
          accessibilityLabel={`Distance unit: ${unit === 'km' ? 'kilometers' : 'miles'}`}
        >
          <Text style={styles.toggleText}>{unit}</Text>
        </TouchableOpacity>
      </View>
      {denied && <Text style={styles.warn}>Location permission denied — showing all places.</Text>}
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && sorted.length === 0 && <Text style={styles.empty}>No places nearby.</Text>}
      {!loading && !error && (
        <FlatList data={sorted} renderItem={renderItem} keyExtractor={i => i.place.id} />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', padding: 16 },
  title: { color: colors.text, fontSize: 20, fontWeight: '700' },
  toggle: { backgroundColor: colors.surface, borderRadius: 6, paddingHorizontal: 12, paddingVertical: 6 },
  toggleText: { color: colors.accent, fontWeight: '700' },
  warn: { color: colors.warn, fontSize: 11, paddingHorizontal: 16 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 16, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: colors.border },
  icon: { fontSize: 20, width: 28 },
  info: { flex: 1 },
  name: { color: colors.text, fontWeight: '600' },
  meta: { color: colors.muted, fontSize: 11, marginTop: 2 },
  distance: { color: colors.muted, fontVariant: ['tabular-nums'] },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
